(window.__quranSurahs=window.__quranSurahs||{})[83]={"nomPhon":"Al-Mutaffifin","versets":{"1":{"text":"Malheur aux fraudeurs","arabe":"وَيْلٌۭ لِّلْمُطَفِّفِينَ"},"2":{"text":"qui, lorsqu'ils font mesurer pour eux-mêmes exigent la pleine mesure,","arabe":"ٱلَّذِينَ إِذَا ٱكْتَالُوا۟ عَلَى ٱلنَّاسِ يَسْتَوْفُونَ"},"3":{"text":"et qui lorsqu'eux-mêmes mesurent ou pèsent pour les autres, [leur] causent perte.","arabe":"وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ"},"4":{"text":"Ceux-là ne pensent-ils pas qu'ils seront ressuscités,","arabe":"أَلَا يَظُنُّ أُو۟لَٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ"},"5":{"text":"en un jour terrible,","arabe":"لِيَوْمٍ عَظِيمٍۢ"},"6":{"text":"le jour où les gens se tiendront debout devant le Seigneur de l'Univers?","arabe":"يَوْمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلْعَٰلَمِينَ"},"7":{"text":"Non...! Mais en vérité le livre des libertins sera dans le Sijjîn -","arabe":"كَلَّآ إِنَّ كِتَٰبَ ٱلْفُجَّارِ لَفِى سِجِّينٍۢ"},"8":{"text":"et qui te dira ce qu'est le Sijjîn? -","arabe":"وَمَآ أَدْرَىٰكَ مَا سِجِّينٌۭ"},"9":{"text":"Un livre déjà cacheté (achevé).","arabe":"كِتَٰبٌۭ مَّرْقُومٌۭ"},"10":{"text":"Malheur, ce jour-là, aux négateurs,","arabe":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ"},"11":{"text":"qui démentent le jour de la Rétribution.","arabe":"ٱلَّذِينَ يُكَذِّبُونَ بِيَوْمِ ٱلدِّينِ"},"12":{"text":"Or, ne le dément que tout transgresseur, pécheur:","arabe":"وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ"},"13":{"text":"qui, lorsque Nos versets lui sont récités, dit: «[Ce sont] des contes d'anciens!»","arabe":"إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ"},"14":{"text":"Pas du tout, mais ce qu'ils ont accompli couvre leurs cœurs.","arabe":"كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ يَكْسِبُونَ"},"15":{"text":"Qu'ils prennent garde! En vérité ce jour-là un voile les empêchera de voir leur Seigneur,","arabe":"كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍۢ لَّمَحْجُوبُونَ"},"16":{"text":"ensuite, ils brûleront certes, dans la Fournaise;","arabe":"ثُمَّ إِنَّهُمْ لَصَالُوا۟ ٱلْجَحِيمِ"},"17":{"text":"on [leur] dira alors: «Voilà ce que vous traitiez de mensonge!»","arabe":"ثُمَّ يُقَالُ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ"},"18":{"text":"Qu'ils prennent garde! Le livre des bons sera dans l'Illiyûn -","arabe":"كَلَّآ إِنَّ كِتَٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ"},"19":{"text":"et qui te dira ce qu'est l'Illiyûn? -","arabe":"وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ"},"20":{"text":"un livre cacheté!","arabe":"كِتَٰبٌۭ مَّرْقُومٌۭ"},"21":{"text":"Les rapprochés [d'Allah: les Anges] en témoignent.","arabe":"يَشْهَدُهُ ٱلْمُقَرَّبُونَ"},"22":{"text":"Les bons seront dans [un Jardin] de délice,","arabe":"إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ"},"23":{"text":"sur les divans, ils regardent.","arabe":"عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ"},"24":{"text":"Tu reconnaîtras sur leurs visages, l'éclat de la félicité.","arabe":"تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ"},"25":{"text":"On leur sert à boire un nectar pur, cacheté,","arabe":"يُسْقَوْنَ مِن رَّحِيقٍۢ مَّخْتُومٍ"},"26":{"text":"laissant un arrière-goût de musc. Que ceux qui la convoitent entrent en compétition [pour l'acquérir]","arabe":"خِتَٰمُهُۥ مِسْكٌۭ ۚ وَفِى ذَٰلِكَ فَلْيَتَنَافَسِ ٱلْمُتَنَٰفِسُونَ"},"27":{"text":"Il est mélangé à la boisson de Tasnîm,","arabe":"وَمِزَاجُهُۥ مِن تَسْنِيمٍ"},"28":{"text":"source dont les rapprochés boivent.","arabe":"عَيْنًۭا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ"},"29":{"text":"Les criminels riaient de ceux qui croyaient,","arabe":"إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ"},"30":{"text":"et, passant près d'eux, ils se faisaient des œillades,","arabe":"وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ"},"31":{"text":"et, retournant dans leurs familles, ils retournaient en plaisantant,","arabe":"وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ"},"32":{"text":"et les voyant, ils disaient: «Ce sont vraiment ceux-là les égarés».","arabe":"وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ"},"33":{"text":"Or, ils n'ont pas été envoyés pour être leurs gardiens.","arabe":"وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَٰفِظِينَ"},"34":{"text":"Aujourd'hui, donc, ce sont ceux qui ont cru qui rient des infidèles","arabe":"فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ"},"35":{"text":"sur les divans, ils regardent.","arabe":"عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ"},"36":{"text":"Est-ce que les infidèles ont eu la récompense de ce qu'ils faisaient?","arabe":"هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ"}}};